{
  "summary": "Définir et exécuter un instrument pour calculer la valeur minimax du jeu d’allocation de ressources.",
  "actions": [
    {
      "tool": "construct_instrument",
      "name": "minimax.json",
      "spec": {
        "inputs": ["x", "y"],
        "name": "minimax",
        "outputs": {
          "value": {
            "args": [
              {
                "field": "x"
              },
              {
                "field": "y"
              }
            ],
            "op": "min"
          },
          "witness": {
            "args": [
              {
                "field": "x"
              },
              {
                "field": "y"
              }
            ],
            "op": "max"
          }
        }
      }
    },
    {
      "tool": "run_instrument",
      "name": "minimax.json",
      "input": {
        "x": 0.5,
        "y": 0.5
      }
    }
  ],
  "done": false
}
